    const demi = (cx, cy, rx, ry, dos) => `<path class="${dos ? "g-cache-arc" : "g-arc-plein"}" d="M${f(cx - rx)} ${f(cy)} A${f(rx)} ${f(ry)} 0 0 ${dos ? 1 : 0} ${f(cx + rx)} ${f(cy)}"/>`;
