  FIGURES["ld-meth-traduire"] = () => droite({ min: 0, max: 12, points: ldSuite(6, 12).map((x) => ({ x })), aria: "Valeurs de 0 à 12 : on garde les entiers 6 à 12 pour l'événement X ⩾ 6, le contraire est X ⩽ 5" });
