    const p = (d * d - a * a - b * b) / 2, bd2 = 2 * a * a + 2 * b * b - d * d, qBD = Math.random() < 0.5, pT = p < 0 ? `(${fr(p)})` : fr(p);
    const sol1 = `$\\overrightarrow{AC} = \\overrightarrow{AB} + \\overrightarrow{AD}$, donc $AC^2 = AB^2 + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + AD^2$ : $${d * d} = ${a * a} + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + ${b * b}$, d'où $\\overrightarrow{AB} \\cdot \\overrightarrow{AD} = \\dfrac{${d * d} - ${a * a} - ${b * b}}{2} = ${fr(p)}$.`;
