    for (let k = 1; k <= n; k++) { ys.push(ys[k - 1] + (monte ? 1 : -1) * rand(3, 7)); monte = !monte; }
    const cases = []; for (let k = 0; k < n; k++) { cases.push(ys[k + 1] > ys[k] ? "+" : "-"); if (k < n - 1) cases.push("0"); }
    const ecart = Math.random() < 0.15 ? 2 : 0;
