  // fonctions continues strictement croissantes sur [n ; n + 1] (n ⩾ 0) qui s'annulent une fois : { tex, f, n }
  function tlfFamille() {
    const T = pick([
      () => { let c; do { c = rand(2, 60); } while (Number.isInteger(Math.sqrt(c))); return { tex: `x^2 - ${c}`, f: (x) => x * x - c }; },
      () => { let c; do { c = rand(2, 100); } while (Number.isInteger(Math.round(Math.cbrt(c) * 1e9) / 1e9)); return { tex: `x^3 - ${c}`, f: (x) => x ** 3 - c }; },
      () => { const c = rand(2, 40); return { tex: `e^x - ${c}`, f: (x) => Math.exp(x) - c }; },
      () => { const p = rand(1, 4), c = rand(1, 25); return { tex: `x^3 + ${p === 1 ? "" : p}x - ${c}`, f: (x) => x ** 3 + p * x - c }; },
      () => { const p = rand(1, 5), c = rand(2, 30); return { tex: `x^2 + ${p === 1 ? "" : p}x - ${c}`, f: (x) => x * x + p * x - c }; },
      () => { const p = rand(1, 3), c = rand(2, 15); return { tex: `e^x + ${p === 1 ? "" : p}x - ${c}`, f: (x) => Math.exp(x) + p * x - c }; }
    ])();
    let n = 0; while (T.f(n + 1) <= 0) n++;
    let lo = n, hi = n + 1; for (let k = 0; k < 60; k++) { const m = (lo + hi) / 2; if (T.f(m) <= 0) lo = m; else hi = m; }
    return Object.assign(T, { n, r: lo });
  }

