  FIGURES["tdc-symetrie"] = () => graph(tsuEtiquettes({ xmin: -0.5, xmax: 6.6, ymin: -0.5, ymax: 6.6, h: 300, curves: [{ f: (x) => x * x, a: 0, b: 2.5, closed: false, label: "y = x²", auto: true }, { f: (x) => Math.sqrt(x), a: 0, b: 6.3, closed: false, label: "y = √x", auto: true }], chemins: [[[0, 0], [6.4, 6.4]]], points: [{ x: 2, y: 4, label: "(2 ; 4)", auto: true }, { x: 4, y: 2, label: "(4 ; 2)", auto: true }], aria: "Sur [0 ; +∞[, les courbes de x² et de √x sont symétriques par rapport à la droite y = x : le point (2 ; 4) correspond au point (4 ; 2)" }));
