  /* ---------- Terminale maths complémentaires, chapitre 13 : lois à densité (préfixe tld-) ---------- */
  const tldCourt = (x) => Math.abs(x * 1e6 - Math.round(x * 1e6)) < 1e-6 * Math.max(1, Math.abs(x));
  // valeur exacte p/q écrite en décimal si possible, sinon en fraction irréductible
  const tldQ = (p, q) => (tldCourt(p / q) ? nb(+(p / q).toFixed(6)) : frac(p, q));
  // erreur « valeur approchée » d'une réponse non décimale (règle : on demande la valeur exacte)
  const tldApprox = (v) => (tldCourt(v) ? [] : [{ valeur: +v.toFixed(2), message: "C'est une valeur approchée : donne la valeur exacte, sous forme de fraction." }]);
