  /* ---------- Terminale maths complémentaires, chapitre 10 : loi géométrique et temps d'attente (préfixe tlg-) ---------- */
  FIGURES["tlg-batons"] = () => graph({ xmin: -0.4, xmax: 11, ymin: -0.03, ymax: 0.36, ystep: 0.05, yetiq: 0.1, xetiq: 2, padL: 34, h: 230, xlabel: "k", ylabel: "P(X = k)", bars: Array.from({ length: 10 }, (_, i) => ({ x: i + 1, y: 0.3 * 0.7 ** i })), aria: "Loi géométrique de paramètre 0,3 : P(X = k) = 0,7 puissance k−1 fois 0,3, des bâtons qui diminuent : 0,3 ; 0,21 ; 0,147…" });
  FIGURES["tlg-crue"] = () => graph({ xmin: -10, xmax: 310, ymin: -0.06, ymax: 1.12, xstep: 50, xetiq: 100, ystep: 0.1, yetiq: 0.2, padL: 30, h: 250, xlabel: "années", ylabel: "probabilité", curves: [{ f: (n) => 1 - 0.99 ** n, a: 0, b: 300, closed: false }], hlines: [{ y: 0.5, label: "0,5" }], points: [{ x: 69, y: 1 - 0.99 ** 69, label: "69 ans" }, { x: 100, y: 1 - 0.99 ** 100, label: "100 ans : ≈ 0,63" }], aria: "Probabilité d'au moins une crue centennale en n années : 0,5 vers 69 ans, environ 0,63 en 100 ans" });

  const tlgP = () => pick([0.1, 0.2, 0.25, 0.3, 0.4, 0.5, 1 / 6]);
  const tlgTex = (p) => (Math.abs(p - 1 / 6) < 1e-9 ? "\\dfrac{1}{6}" : nb(p));
  const tlgTexQ = (p) => (Math.abs(p - 1 / 6) < 1e-9 ? "\\dfrac{5}{6}" : nb(+(1 - p).toFixed(4)));
  const tlgTxt = (x) => String(+(+x).toFixed(4)).replace(".", ",");
  // Bâtons de la loi géométrique de paramètre p (k de 1 à kmax) ; sel(k) vrai : bâton coloré ; o.cum : probabilités cumulées P(X ≤ k)
  function tlgBatons(p, kmax, sel, o) {
    o = o || {};
    const W = 320, H = o.h || 200, gx = 40, dx = 8, hy = 16, by = 24, val = (k) => (o.cum ? 1 - (1 - p) ** k : (1 - p) ** (k - 1) * p);
    const max = o.cum ? 1 : p, pas = max > 0.6 ? 0.2 : max > 0.3 ? 0.1 : max > 0.15 ? 0.05 : max > 0.06 ? 0.02 : 0.01, top = Math.ceil((max * 1.1) / pas - 1e-9) * pas;
    const Y = (y) => +(H - by - (y / top) * (H - by - hy)).toFixed(1), bw = (W - gx - dx) / kmax;
    let s = `<svg class="graph" viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria}"><g class="g-grid">`;
    for (let y = pas; y <= top + 1e-9; y += pas) s += `<line x1="${gx}" y1="${Y(y)}" x2="${W - dx}" y2="${Y(y)}"/>`;
    s += `</g><g class="g-tick">`;
    for (let y = 0; y <= top + 1e-9; y += 2 * pas) s += `<text x="${gx - 4}" y="${Y(y) + 3.5}" text-anchor="end">${tlgTxt(y)}</text>`;
    const pasK = kmax > 20 ? 5 : kmax > 10 ? 2 : 1;
    for (let k = 1; k <= kmax; k++) if (k === 1 || k % pasK === 0) s += `<text x="${(gx + (k - 0.5) * bw).toFixed(1)}" y="${H - by + 13}" text-anchor="middle">${k}</text>`;
    s += `<text x="${gx - 8}" y="${H - by + 13}" text-anchor="end">k :</text></g>`;
    for (let k = 1; k <= kmax; k++) s += `<rect class="${sel(k) ? "g-barre-plus" : "g-rect"}" x="${(gx + (k - 0.5) * bw - Math.min(6, bw * 0.3)).toFixed(1)}" y="${Y(val(k))}" width="${Math.min(12, bw * 0.6).toFixed(1)}" height="${(Y(0) - Y(val(k))).toFixed(1)}"/>`;
    s += `<g class="g-axis"><line x1="${gx}" y1="${Y(0)}" x2="${W - dx}" y2="${Y(0)}"/><line x1="${gx}" y1="${hy - 6}" x2="${gx}" y2="${Y(0)}"/></g>`;
    if (o.seuil !== undefined) s += `<line class="g-hline" x1="${gx}" y1="${Y(o.seuil)}" x2="${W - dx}" y2="${Y(o.seuil)}"/><text class="g-hlabel" x="${gx + 4}" y="${Y(o.seuil) - 5}">${tlgTxt(o.seuil)}</text>`;
    return s + `<text class="g-label" x="${gx + 6}" y="${hy - 4}">${o.cum ? "P(X ⩽ k)" : "P(X = k)"}</text></svg>`;
  }
  FIGURES["tlg-cours-plus"] = () => tlgBatons(0.2, 14, (k) => k > 5, { aria: "Loi géométrique de paramètre 0,2 : les bâtons de k = 6 à 14 (en couleur) correspondent à X > 5 ; leur somme, jusqu'à l'infini, vaut 0,8⁵ ≈ 0,328" });
  FIGURES["tlg-cours-esperance"] = () => tlgBatons(0.25, 16, (k) => k === 4, { aria: "Loi géométrique de paramètre 0,25 : le bâton k = 4, en couleur, est la valeur de l'espérance 1/0,25 = 4 ; les bâtons décroissent mais la loi « s'étale » loin à droite" });
  FIGURES["tlg-cours-seuil"] = () => tlgBatons(1 / 6, 24, (k) => k >= 17, { cum: true, seuil: 0.95, h: 210, aria: "Probabilités cumulées P(X ⩽ k) pour un dé (p = 1/6) : elles dépassent 0,95 à partir de k = 17 (bâtons en couleur)" });
